SELECT 

WHERE c.root_comment_id = #{rootId}
ORDER BY c.created_at, c.id

INSERT INTO comments (post_id, user_id, parent_comment_id, root_comment_id, content)
SELECT pc.post_id, #{userId}, pc.id, COALESCE(pc.root_comment_id, pc.id), #{content}
FROM comments pc
WHERE pc.id = #{parentId} AND pc.post_id = #{postId}
RETURNING id
